#!/usr/bin/env python3
# Generated By: Claude Code (Claude Opus 4.6)
"""Red/green test validation for PR-scoped reviews.

Identifies test files in the PR diff, runs them against the merge base
(pre-fix) and HEAD (post-fix). Produces synthetic findings when tests
don't demonstrate red-to-green behavior.

Findings are written to --findings-dir in merged-finding schema format
alongside existing review findings. The render step picks them up
naturally.
"""

import argparse
import json
import logging
import re
import subprocess
import sys
from pathlib import Path

SKILL_ROOT = Path(__file__).resolve().parent.parent
PLUGIN_ROOT = SKILL_ROOT.parent.parent

sys.path.insert(0, str(PLUGIN_ROOT))
from scripts.envelope import content_hash  # noqa: E402

logger = logging.getLogger("redgreen-validate")

TEST_FILE_PATTERN = re.compile(r"(^|/)test_.*\.py$|_test\.py$")
SOURCE_FILE_PATTERN = re.compile(r"\.py$")


def _git(*args: str, cwd: str | None = None) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", *args],
        capture_output=True,
        text=True,
        cwd=cwd,
    )


DEFAULT_TIMEOUT = 30
SKIP_PATTERN_DEFAULT = r"integration|e2e|functional"


def _run_test(
    test_file: str,
    cwd: str | None = None,
    timeout: int = DEFAULT_TIMEOUT,
    setup_command: str = "",
    test_command: str = "",
) -> tuple[str, str]:
    """Run a single test file. Returns ('pass', 'fail', or 'timeout') + output."""
    if test_command:
        cmd = test_command.replace("{file}", test_file)
    else:
        cmd = f"{sys.executable} -m pytest {test_file} -x --tb=short -q"

    if setup_command:
        cmd = f"{setup_command} && {cmd}"

    try:
        result = subprocess.run(
            ["bash", "-c", cmd],
            capture_output=True,
            text=True,
            cwd=cwd,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        return "timeout", f"Test timed out after {timeout}s"
    output = (result.stdout + result.stderr).strip()
    if result.returncode == 0:
        return "pass", output
    return "fail", output


def _make_finding(
    *,
    title: str,
    issue: str,
    why_it_matters: str,
    suggested_fix: str,
    locations: list[dict],
    runtime_scope: str,
    runtime_scope_justification: str,
    failure_mode: str,
    failure_mode_justification: str,
    hash_salt: str,
) -> dict:
    primary_loc = locations[0]
    chash = content_hash("test", "redgreen", primary_loc["path"], primary_loc["line"], title, hash_salt)
    return {
        "content_hash": chash,
        "concern_slug": "test",
        "source_dimensions": ["redgreen"],
        "title": title,
        "runtime_scope": runtime_scope,
        "runtime_scope_justification": runtime_scope_justification,
        "failure_mode": failure_mode,
        "failure_mode_justification": failure_mode_justification,
        "evidence_quality": "demonstrated",
        "evidence_quality_justification": "Verified by running tests against pre-fix and post-fix code",
        "trace_origin": "entry-point",
        "trace_origin_justification": "Checked PR diff against merge base",
        "effort_to_fix": "small",
        "effort_to_fix_justification": "Add or fix a regression test",
        "locations": locations,
        "issue": issue,
        "why_it_matters": why_it_matters,
        "suggested_fix": suggested_fix,
    }


def _untested_change_finding(changed_source_files: list[str]) -> dict:
    locations = [{"path": changed_source_files[0], "line": "1", "role": "primary"}]
    locations += [{"path": f, "line": "1", "role": "related"} for f in changed_source_files[1:]]
    return _make_finding(
        title="No regression tests for code changes",
        issue=f"PR modifies {len(changed_source_files)} source file(s) but adds/modifies no test files",
        why_it_matters="Without regression tests, fixes can silently regress",
        suggested_fix="Add test(s) that fail against the pre-fix code and pass after the fix",
        locations=locations,
        runtime_scope="service-external",
        runtime_scope_justification="Changed production code has no test demonstrating the fix",
        failure_mode="data-loss-or-security",
        failure_mode_justification="Untested fix may regress silently, risking data loss or security issues",
        hash_salt="no-tests",
    )


def _test_passes_before_fix_finding(test_file: str) -> dict:
    return _make_finding(
        title=f"Test passes before fix: {Path(test_file).name}",
        issue=f"{test_file} passes against pre-fix code — does not demonstrate the failure it claims to test",
        why_it_matters="A regression test must fail before the fix to prove it catches the bug",
        suggested_fix="Revise the test to assert behavior that fails without the fix",
        locations=[{"path": test_file, "line": "1", "role": "primary"}],
        runtime_scope="service-external",
        runtime_scope_justification="Test does not prove the production fix addresses a real failure",
        failure_mode="data-loss-or-security",
        failure_mode_justification="Test provides false confidence — regression would go undetected",
        hash_salt="no-red",
    )


def _test_fails_after_fix_finding(test_file: str, output: str = "") -> dict:
    detail = f"\n\n```\n{output}\n```" if output else ""
    return _make_finding(
        title=f"Test fails after fix: {Path(test_file).name}",
        issue=f"{test_file} fails against post-fix code — fix does not resolve the test failure{detail}",
        why_it_matters="Test fails at both pre-fix and post-fix states — either the fix is incomplete or the test is broken",
        suggested_fix="Fix the implementation or correct the test assertions",
        locations=[{"path": test_file, "line": "1", "role": "primary"}],
        runtime_scope="ci",
        runtime_scope_justification="Test failure in CI indicates build/test breakage",
        failure_mode="build-break",
        failure_mode_justification="Test fails at HEAD — CI would reject this PR",
        hash_salt="no-green",
    )


def _tests_unrunnable_finding(test_entries: list[tuple[str, str, str] | str]) -> dict:
    # Accept list of (file, red_output, green_output) tuples or plain strings
    if test_entries and isinstance(test_entries[0], tuple):
        files = [t[0] for t in test_entries]
        outputs = "\n\n".join(
            f"**{Path(t[0]).name}**:\n```\n{t[1]}\n```"
            for t in test_entries
        )
    else:
        files = list(test_entries)
        outputs = ""
    locations = [{"path": files[0], "line": "1", "role": "primary"}]
    locations += [{"path": f, "line": "1", "role": "related"} for f in files[1:]]
    file_list = ", ".join(Path(f).name for f in files)
    detail = f"\n\n{outputs}" if outputs else ""
    return _make_finding(
        title=f"Cannot run {len(files)} test file(s)",
        issue=f"Tests fail at both pre-fix and post-fix states: {file_list}{detail}",
        why_it_matters="Red/green validation impossible — test coverage for this PR is unverifiable",
        suggested_fix="Ensure tests can run independently with: python -m pytest <file>",
        locations=locations,
        runtime_scope="service-external",
        runtime_scope_justification="Cannot verify test coverage for production code changes",
        failure_mode="data-loss-or-security",
        failure_mode_justification="Unverifiable test coverage risks undetected regressions",
        hash_salt="unrunnable",
    )


def evaluate_results(
    red_results: dict[str, tuple[str, str]],
    green_results: dict[str, tuple[str, str]],
) -> list[dict]:
    """Produce findings from red/green test results. Pure function, no I/O.

    Statuses: 'pass', 'fail', 'timeout'. Timeout treated as non-pass.
    """
    findings: list[dict] = []
    unrunnable: list[tuple[str, str, str]] = []
    for tf in red_results:
        red_status, red_output = red_results[tf]
        green_status, green_output = green_results[tf]
        red_ok = red_status == "pass"
        green_ok = green_status == "pass"

        if not red_ok and not green_ok:
            unrunnable.append((tf, red_output, green_output))
        elif red_ok and green_ok:
            findings.append(_test_passes_before_fix_finding(tf))
        elif not red_ok and green_ok:
            pass
        elif red_ok and not green_ok:
            findings.append(_test_fails_after_fix_finding(tf, green_output))

    if unrunnable:
        findings.append(_tests_unrunnable_finding(unrunnable))
    return findings


def _resolve_merge_base(project: str) -> str | None:
    result = _git("symbolic-ref", "refs/remotes/origin/HEAD", cwd=project)
    if result.returncode != 0:
        return None
    default_branch = result.stdout.strip().replace("refs/remotes/", "")
    if not default_branch:
        return None
    result = _git("merge-base", "HEAD", default_branch, cwd=project)
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--findings-dir",
        type=Path,
        required=True,
        help="20-findings/ directory to write synthetic findings into",
    )
    parser.add_argument(
        "--project-root",
        type=Path,
        default=Path("."),
        help="project root for git operations (default: cwd)",
    )
    parser.add_argument(
        "--setup-command",
        default="",
        help="command to run before tests (e.g. 'source .venv/bin/activate'). Runs once per phase.",
    )
    parser.add_argument(
        "--test-command",
        default="",
        help="custom test command with {file} placeholder (e.g. 'make test-unit FILE={file}'). Default: python -m pytest.",
    )
    parser.add_argument(
        "--strip-prefix",
        default="",
        help="path prefix to strip from test file paths (e.g. 'backend/' when tests run from a subdirectory)",
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=DEFAULT_TIMEOUT,
        help=f"per-test-file timeout in seconds (default: {DEFAULT_TIMEOUT})",
    )
    parser.add_argument(
        "--skip-pattern",
        default=SKIP_PATTERN_DEFAULT,
        help=f"regex to exclude test paths (default: '{SKIP_PATTERN_DEFAULT}'). Empty string disables.",
    )
    parser.add_argument("--debug", action="store_true")
    args = parser.parse_args(argv)

    logging.basicConfig(
        level=logging.DEBUG if args.debug else logging.INFO,
        format="%(levelname)s: %(message)s",
        stream=sys.stderr,
    )

    project = str(args.project_root.resolve())

    merge_base = _resolve_merge_base(project)
    if not merge_base:
        print("OK: no merge base found — skipping red/green validation (not a PR review)")
        return 0

    # Record branch name so we restore to branch, not detached SHA
    branch_result = _git("symbolic-ref", "--short", "HEAD", cwd=project)
    if branch_result.returncode == 0:
        args.head = branch_result.stdout.strip()
    else:
        # Already detached — fall back to SHA
        sha_result = _git("rev-parse", "HEAD", cwd=project)
        if sha_result.returncode != 0:
            logger.error("git rev-parse HEAD failed")
            return 1
        args.head = sha_result.stdout.strip()

    args.merge_base = merge_base
    head_sha = _git("rev-parse", "HEAD", cwd=project).stdout.strip()

    diff_result = _git("diff", "--name-only", f"{args.merge_base}..{head_sha}", cwd=project)
    if diff_result.returncode != 0:
        logger.error("git diff failed: %s", diff_result.stderr)
        return 1

    all_changed = [f for f in diff_result.stdout.strip().splitlines() if f]
    test_files = [f for f in all_changed if TEST_FILE_PATTERN.search(f)]
    source_files = [f for f in all_changed if SOURCE_FILE_PATTERN.search(f) and not TEST_FILE_PATTERN.search(f)]

    if args.skip_pattern and test_files:
        skip_re = re.compile(args.skip_pattern)
        before = len(test_files)
        test_files = [f for f in test_files if not skip_re.search(f)]
        skipped = before - len(test_files)
        if skipped:
            logger.info("--skip-pattern excluded %d test file(s)", skipped)

    if not source_files:
        print("OK: no Python source files changed — skipping red/green validation")
        return 0

    findings: list[dict] = []

    if not test_files:
        logger.info("no test files in PR diff — producing critical finding")
        findings.append(_untested_change_finding(source_files))
    else:
        head_ref = args.head
        checkout_done = False
        red_results: dict[str, tuple[str, str]] = {}
        green_results: dict[str, tuple[str, str]] = {}

        try:
            # --- RED phase: checkout merge base, restore all test files, run all ---
            logger.info("checking out merge base %s", args.merge_base[:12])
            co = _git("checkout", args.merge_base, cwd=project)
            if co.returncode != 0:
                logger.error("git checkout merge base failed: %s", co.stderr)
                return 1
            checkout_done = True

            runnable = []
            for tf in test_files:
                _git("checkout", head_ref, "--", tf, cwd=project)
                if (Path(project) / tf).exists():
                    runnable.append(tf)
                else:
                    logger.warning("test file %s not found after checkout — skipping", tf)

            prefix = args.strip_prefix
            for tf in runnable:
                run_path = tf[len(prefix):] if prefix and tf.startswith(prefix) else tf
                logger.info("RED phase: running %s at merge base", tf)
                status, output = _run_test(run_path, cwd=project, timeout=args.timeout, setup_command=args.setup_command, test_command=args.test_command)
                logger.info("  result: %s", status)
                logger.debug("  output:\n%s", output)
                red_results[tf] = (status, output)

            # --- GREEN phase: restore HEAD, run all ---
            logger.info("restoring HEAD %s", head_ref[:12])
            _git("checkout", head_ref, cwd=project)
            checkout_done = False

            for tf in runnable:
                run_path = tf[len(prefix):] if prefix and tf.startswith(prefix) else tf
                logger.info("GREEN phase: running %s at HEAD", tf)
                status, output = _run_test(run_path, cwd=project, timeout=args.timeout, setup_command=args.setup_command, test_command=args.test_command)
                logger.info("  result: %s", status)
                logger.debug("  output:\n%s", output)
                green_results[tf] = (status, output)

            findings.extend(evaluate_results(red_results, green_results))

        except Exception as exc:
            logger.error("red/green validation failed: %s", exc)
            findings.append(_make_finding(
                title="Red/green validation aborted",
                issue=f"Validation script failed: {exc}",
                why_it_matters="Could not verify red/green test pattern",
                suggested_fix="Check test environment and retry",
                locations=[{"path": source_files[0], "line": "1", "role": "primary"}],
                runtime_scope="ci",
                runtime_scope_justification="Validation infrastructure failure",
                failure_mode="build-break",
                failure_mode_justification="Validation could not complete",
                hash_salt="abort",
            ))
        finally:
            if checkout_done:
                logger.info("restoring HEAD %s", head_ref[:12])
                _git("checkout", head_ref, cwd=project)

    if not findings:
        print(f"OK: all {len(test_files)} test file(s) validated (red/green confirmed)")
        return 0

    args.findings_dir.mkdir(parents=True, exist_ok=True)
    for f in findings:
        fpath = args.findings_dir / f"{f['content_hash']}.json"
        with fpath.open("w", encoding="utf-8") as fh:
            json.dump(f, fh, indent=2)
            fh.write("\n")
        logger.info("wrote finding: %s (%s)", fpath.name, f["title"][:60])

    print(
        f"red/green: {len(findings)} finding(s) written, "
        f"{len(test_files)} test file(s) checked"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
